export function clamp(value, low, high) {
  if (value < low) {
    return low;
  }
  if (value > high) {
    return high;
  }
  return value;
}

test("below range", () => { assert.equal(clamp(-5, 0, 10), 0); });
test("inside range", () => { assert.equal(clamp(5, 0, 10), 5); });
test("above range", () => { assert.equal(clamp(15, 0, 10), 10); });
test("at low boundary", () => { assert.equal(clamp(0, 0, 10), 0); });
test("at high boundary", () => { assert.equal(clamp(10, 0, 10), 10); });
